mapper.select:
select dict_type as dictType, field_type as fieldType, field_name as fieldName, parent_id as parentId, remarks, tenant_id, select_able, sort_no from la_dict_info where enable_state = 1 and ( tenant_id is null
or tenant_id = #{tenantId}
)
and dict_type like #{type}
group by dict_type,field_type,field_name,parent_id,tenant_id,remarks,select_able,sort_no order by sort_no asc

select di.id, di.dict_type , di.field_type , di.field_name , di.sort_no, di.remarks, di.tenant_id, di.updated_at , di.updated_by , di.created_by , di.created_at , di.enable_state , dt.dict_name, di.extra, di.select_able from la_dict_info di inner join la_dict_type dt on dt.dict_type = di.dict_type where di.dict_type = #{dictInfo.dictType} and ( di.tenant_id is null
or di.tenant_id = #{dictInfo.tenantId}
)
and di.id = #{dictInfo.id}
or di.parent_keys like #{dictInfo.parentId}
and di.level <= #{dictInfo.level}

select di.id, di.dict_type , di.field_type , di.field_name , di.sort_no, di.remarks, di.tenant_id, di.updated_at , di.updated_by , di.created_by , di.created_at , di.enable_state , di.parent_id , di.parent_keys , di.extra, di.select_able from la_dict_info di inner join la_dict_type dt on dt.dict_type = di.dict_type where di.enable_state = 1 and ( di.tenant_id is null
or di.tenant_id = #{tenantId}
) and dt.id in
#{item}
